  "MARKETING_TARGET_TYPE_RENOVATION_SERVICES",
  "MARKETING_TARGET_TYPE_FURNITURE_AND_BUILDING_MATERIALS",
  "MARKETING_TARGET_TYPE_EXHIBITION_SALES",
